 # http://code.activestate.com/recipes/577821-integer-square-root-function/
 def isqrt(x):
     "returns int(floor(sqrt(x))) using only integer math"
     assert x >= 0, 'Undefined %r' % locals()
     n = int(x)
     if n == 0:
         return 0
     a, b = divmod(n.bit_length(), 2)
     x = 2**(a+b)
     while True:
         y = (x + n//x)//2
         if y >= x:
             return x
         x = y

