 def check_row(row):
 	if row.count('X') == 4:
 		return 'X'
 	if row.count('O') == 4:
 		return 'O'
 	if row.count('X') == 3 and row.count('T') == 1:
 		return 'X'
 	if row.count('O') == 3 and row.count('T') == 1:
 		return 'O'
 	if row.count('.') > 0:
 		return '.'
 	return 'F'


 def calc_result(case):
 	case = case[:-1]
 	print "\t%s" % case

 	rows = []
 	for row in case:
 		#print "\trow: '%s'" % row[0]
 		rows.append(row[0])

 	for i in xrange(4):
 		column = ""
 		for j in xrange(4):
 			column += case[j][0][i]
 		#print "\trow: '%s'" % column
 		rows.append(column)

 	diag1 = ""
 	diag2 = ""
 	for i in xrange(4):
 		diag1 += case[i][0][i]
 		diag2 += case[3-i][0][i]
 	#print "\trow: '%s'" % diag1
 	#print "\trow: '%s'" % diag2
 	rows.append(diag1)
 	rows.append(diag2)

 	res = []
 	for row in rows:
 		res.append(check_row(row))

 	if res.count('X'):
 		if res.count('O'):
 			raise IOError('both X and O won')
 		else:
 			result = "X won"
 	else:
 		if res.count('O'):
 			result = "O won"
 		else:
 			if res.count('.'):
 				result = "Game has not completed"
 			else:
 				result = "Draw"

 	print "\t%s" % res
 	print "\t%s" % result

 	return result

