 for case in range(1, T + 1):
     RR, CC, M = map(int, fin.readline().split())
     R, C = None, None
     blocks = RR*CC - M
     inverse = False
     if RR > CC:
         inverse = True
         R, C = CC, RR
     else:
         R, C = RR, CC
     result = None
     # Now R <= C
     if R == 1:
         # Always possible
         result = [('.' * blocks) + ('*' * M)]
     elif R == 2:
         # Possible if blocks == 1 or blocks % 2 == 0
         if blocks == 1:
             result = ['.' + ('*' * (C-1)), '*' * C]
         elif blocks % 2 == 0 and blocks != 2:
             cc = blocks // 2
             result = [('.' * cc) + ('*' * (C - cc)), ('.' * cc) + ('*' * (C - cc))] 
         else:
             result = None
     else:
         if blocks == 1:
             result = ['*' * C] * R
         elif blocks == 4:
             result = ['..' + (C-2)*'*']*2
             result += ['*'*C] * (R-2)
         elif blocks == 6:
             result = ['...' + (C-3)*'*']*2
             result += ['*'*C] * (R-2)
         for rows in range(3, R+1):
             for columns in range(rows, C+1):
                 size = rows * columns
                 if size - blocks >= 0:
                     if size - blocks <= columns - 2: 
                         result = []
                         for r in range(rows):
                             if r < rows - 1:
                                 result.append(('.' * columns) + ('*' * (C - columns)))
                             else:
                                 cc = columns - (size - blocks)
                                 result.append(('.' * cc) + ('*' * (C - cc)))
                         for r in range(R - rows):
                             result.append('*' * C)
                     elif size - blocks == columns - 1 and rows >= 4:
                         result = []
                         for r in range(rows):
                             if r < rows - 2:
                                 result.append(('.' * columns) + ('*' * (C - columns)))
                             elif r == rows - 2:
                                 cc = columns - 1
                                 result.append(('.' * cc) + ('*' * (C - cc)))
                             else:
                                 cc = 2
                                 result.append(('.' * cc) + ('*' * (C - cc)))
                         for r in range(R - rows):
                             result.append('*' * C)




     print("Case #%d: " % (case))
     if result is None:
         debug('impossible', blocks, RR, CC)
