                     if result[rr][cc] == '*':
                         mines += 1
             print(row)
         if mines != M:
             raise Exception("%d != %d %d x %d" % (mines, M, RR, CC))

def ispal(num):
     num = str(num)
     if num == num[::-1]:
         return True
     else:
         return False

 def test(bot, top):
     count = []
     for i in range(bot,top+1):
         if not ((int(i**0.5)**2) == i):
             continue
         if ispal(i) and ispal(int(i**0.5)):
             count.append(i)
     return len(count)

