 def gen_primes():
     """ Generate an infinite sequence of prime numbers.
     from http://stackoverflow.com/questions/1628949/to-find-first-n-prime-numbers-in-python
     """
     D = {}  
     q = 2  

     while True:
         if q not in D:
             yield q        
             D[q * q] = [q]
         else:
             for p in D[q]:
                 D.setdefault(p + q, []).append(p)
             del D[q]

         q += 1



