 def process(N, M):
     lawn = []
     for n in range(N):
         lawn.append([100] * M)
     for n in range(N):
         highest = 0
         for m in range(M):
             if expected[n][m] > highest:
                 highest = expected[n][m]
         for m in range(M):
             if lawn[n][m] > highest:
                 lawn[n][m] = highest
     for m in range(M):
         highest = 0
         for n in range(N):
             if expected[n][m] > highest:
                 highest = expected[n][m]
         for n in range(N):
             if lawn[n][m] > highest:
                 lawn[n][m] = highest
     for n in range(N):
         for m in range(M):
             if lawn[n][m] <> expected[n][m]:
                 return 'NO'
     return 'YES'

