       if numMines >= gridMines:
         break;
       for c in xrange( 0, gridCols ):
         x[ r ][ c ] = '*'
         numMines += 1
         numSpaces -= 1
         if numMines >= gridMines:
           break;

   for r in xrange( 0, R ):
     if sideMines <= 0:
       break
     for c in xrange( gridCols, C ):
       x[ r ][ c ] = '*'
       numMines += 1
       numSpaces -= 1
       sideMines -= 1
       if sideMines <= 0:
         break

   for c in xrange( 0, C ):
     if bottomMines <= 0:
       break
     for r in xrange( gridRows, R ):
       x[ r ][ c ] = '*'
       numMines += 1
       numSpaces -= 1
       bottomMines -= 1
       if bottomMines <= 0:
         break

   x[ R - 1][ C - 1 ] = 'c'

   if numMines != M and ( R * C ) - M != 1:
     print "ERROR!!!!!!!!!!!!!!!!!!!!!!!!"
     print ( R * C ) - M


   o = ""

   if Flip:
     for c in xrange( 0, C ):
       for r in xrange( 0, R ):
          o += x[ r ][ c ]
       o += '\n'
   else:
     for r in xrange( 0, R ):
       for c in xrange( 0, C ):
          o += x[ r ][ c ]
       o += '\n'

   return o[:-1] #strip the extra newline




